// Adapter: the external SDK behind a domain interface
class StripeGatewayAdapter implements PaymentGateway {
    private final StripeClient stripe;
    public Receipt charge(Order o) {
        var charge = stripe.charges().create(o.totalInCents(), "brl");
        return new Receipt(charge.getId());            // translate to a domain type
    }
}

// Decorator: adds logging, keeps the interface
class LoggingGateway implements PaymentGateway {
    private final PaymentGateway delegate;
    public Receipt charge(Order o) {
        log.info("Charging order {}", o.id());
        return delegate.charge(o);
    }
}

// WRONG: the SDK type crosses the boundary
public com.stripe.model.Charge charge(Order o) { ... }

// RIGHT: a domain type
public Receipt charge(Order o) { ... }

public record OrderPaid(Long orderId) {}

@Service
class PaymentService {
    private final ApplicationEventPublisher events;

    @Transactional
    void confirm(Order o) {
        o.markAsPaid();
        events.publishEvent(new OrderPaid(o.id()));
    }
}

@Component
class EmailListener {
    @TransactionalEventListener          // runs after the commit
    void onPaid(OrderPaid event) { /* send the email */ }
}

// WRONG: runs before the commit
@EventListener
void onPaid(OrderPaid event) { emailSender.paymentConfirmed(event.orderId()); }

